type
  Int = class
    N: int64;
    constructor(NN: int64);
    begin
      N := NN;
    end;
    function IsPrime: boolean;
    begin
      Result := True;
      for var i: int64 := 2 to round(sqrt(N)) do
        if N mod i = 0 then
        begin
          Result := False;
          exit;
        end;
    end;
  end;

