// Parallel for with thread-safe list
type
  ListSimple = class
    l := new List<int64>();
    procedure AddPrime(N: int64);
    begin
      var Result := True;
      for var i: int64 := 2 to round(sqrt(N)) do
        if N mod i = 0 then
        begin
          Result := False;
          break;
        end;
      lock l do 
        if Result then
          l.Add(N);
    end;
  end;

var hh := 1000;

begin
  var ls := new ListSimple;
  var ii: int64 := 1265713689181;
  Parallel.For(ii,ii+hh,ls.AddPrime);
  Println(ls.l.Count);
end.

