procedure TestApproxCheb(s:string; a,b:array of real; eps:real);
// a - array of computed values
// b - array of expected values
// eps - allowable absolute error of solutions
begin
  for var i:=0 to a.Length-1 do begin
    var Msg:=s+': found: '+a[i]+', expected '+b[i];
    Assert(Abs(Abs(a[i])-Abs(b[i]))<=eps,Msg);
    end
end;

procedure TestDecomp(s:string; a:array[,] of real; b:array of real;
    roots:array of real; eps:real);
// a - system matrix;
// b - right-hand side vector;
// roots - vector of reference solutions;
// eps - maximum absolute error of solutions
begin
  var oD:=new Decomp(a);
  var Msg:=s+': cond='+oD.cond+' matrix singularity detected';
  var Flag:=oD.cond+1=oD.cond;
  Assert(not Flag,Msg);
  if not Flag then begin
    oD.Solve(b);
    var sum:=b.Zip(roots,(p,q)->Abs(Abs(p)-Abs(q))).Sum;
    Msg:=s+': unacceptable error '+sum+' > '+eps+NewLine+
        'Received : '+b.JoinIntoString(' ')+NewLine+
        'Expected: '+roots.JoinIntoString(' ');
    Assert(sum<=eps,Msg);
    end
end;

